def project_card(p):
    tags = ''.join(f'<span class="tech-tag">{escape(t)}</span>' for t in p['tech'])
    functional = p.get('status') == 'funcional'
    label = 'Funcional' if functional else 'Demonstrativo'
    card_class = ' is-functional' if functional else ''
    badge_class = ' functional-tag' if functional else ''
    repo = f'<a class="project-repo" href="{escape(p["repository"], quote=True)}" target="_blank" rel="noopener noreferrer">Ver código no GitHub ↗</a>' if p.get('repository') else ''
