    badge = 'Projeto educativo · Funcional' if functional else 'Projeto demonstrativo · Dados fictícios'
    badge_class = ' functional-tag' if functional else ''
    status = 'Execução local confirmada pelo autor' if functional else 'Protótipo nesta prévia'
    demo_heading = 'Teste o cálculo do LabDilui.' if functional else 'Experimente a ideia.'
    demo_intro = 'Prévia do cálculo em mL, com um exemplo educativo e entradas editáveis.' if functional else 'Uma pequena demonstração para tornar o projeto concreto.'
    demo_label = 'Calculadora educativa' if functional else 'Demonstração interativa'
    actions = f'<div class="hero-actions"><a class="button" href="#demo-title">Testar cálculo →</a><a class="button secondary" href="{escape(p["repository"], quote=True)}" target="_blank" rel="noopener noreferrer">Ver código no GitHub ↗</a></div>' if p.get('repository') else ''
    if p.get('repository'):
        repository = f'<div><div class="repo-controls"><a class="saved-link" href="{escape(p["repository"], quote=True)}" target="_blank" rel="noopener noreferrer">Ver repositório no GitHub ↗</a></div><p>Endereço do repositório informado por Paulo Vicente.</p></div>'
    else:
        repository = '<div><p>Ideia demonstrativa. Um repositório próprio ainda não foi associado a este projeto.</p></div>'
    sections = [('01','O problema',p['problem']),('02','A solução implementada' if functional else 'A solução demonstrada',p['solution']),('03','O resultado do exemplo',p['result'])]
    story = ''.join(f'<article class="story-item"><span class="mono">{n} / ESTUDO DE CASO</span><h2>{title}</h2><p>{text}</p></article>' for n,title,text in sections)
    body = f'''<main class="wrap" id="main"><a class="breadcrumb" href="/#projetos"><span aria-hidden="true">←</span>Voltar aos projetos</a><section class="case-hero" aria-labelledby="case-title"><div><div class="eyebrow">{p['category']}</div><h1 id="case-title">{p['title']}</h1><p class="case-subtitle">{p['type']}</p><p class="case-intro">{p['description']}</p><span class="demo-tag{badge_class}">{badge}</span>{actions}<div class="case-meta"><div><small>Status</small>{status}</div><div><small>Tecnologias do projeto</small><div class="tech-tags">{tags}</div></div></div></div>{artwork(p)}</section><section class="story-grid" aria-label="Problema, solução e resultado">{story}</section><section class="demo-panel" aria-labelledby="demo-title"><div class="demo-panel-header"><div><h2 id="demo-title">{demo_heading}</h2><p>{demo_intro}</p></div><span class="demo-tag{badge_class}">{demo_label}</span></div><div class="demo-panel-body">{DEMOS[p['slug']]()}</div></section><p class="case-note">{p['next']}</p><div class="case-next">{repository}<a class="next-project" href="/projetos/{next_p['slug']}/">Próximo projeto: {next_p['title']} →</a></div></main>'''
    return page(p['title'] + ' — ' + p['type'], p['description'] + (' Projeto educativo funcional.' if functional else ' Projeto demonstrativo.'), body)

