# Caminhos relativos permitem publicar na raiz ou dentro de um repositório.
import os
import re
for html_path in DIST.rglob('*.html'):
    html = html_path.read_text(encoding='utf-8')
    def relative_url(match):
        attribute, url = match.groups()
        route, separator, fragment = url.partition('#')
        resource = DIST / route.lstrip('/')
        if resource.is_dir():
            resource /= 'index.html'
        relative = os.path.relpath(resource, html_path.parent).replace(os.sep, '/')
        return f'{attribute}="{relative}' + (separator + fragment if separator else '') + '"'
    html = re.sub(r'(href|src)="(/[^"\\]*)"', relative_url, html)
    html_path.write_text(html, encoding='utf-8')
